            locator_type = CollectionModuleUtilLocator
        else:
            raise AnsibleError('invalid module_utils redirect target %s' % '.'.join(target))
        # A locator constructor resolves redirects and could recurse through
        # a chain.  Probe each link here so the dependency walk stays queued.
        locator = locator_type.__new__(locator_type)
        locator.root_length = locator_type.root_length
        if isinstance(locator, LegacyModuleUtilLocator):
